27	template<class T>
28	static int run_direct(int w,int h,int seed,bool audit) {
29	    const size_t n=size_t(w)*size_t(h);
30	    std::vector<T> output(n);
31	    size_t lookup_bytes=0;
32	    if (audit) {
33	        for(size_t i=0;i<n;++i)output[i]=T(calibration(double(measurement(i,seed))));
34	    } else {
35	        // Measurements are floats in [0,1].  A dense uniform table keeps the
36	        // expensive logarithms out of the per-reading production loop; linear
37	        // interpolation is far more accurate than the normal-mode tolerance.
38	        static const std::vector<float> table=[] {
39	            constexpr size_t intervals=65536;
40	            std::vector<float> values(intervals+1);
41	            for(size_t j=0;j<=intervals;++j)
42	                values[j]=float(calibration(double(j)/double(intervals)));
43	            return values;
44	        }();
45	        lookup_bytes=table.capacity()*sizeof(float);
46	        constexpr float scale=65536.0f;
47	        for(size_t i=0;i<n;++i) {
48	            const float position=measurement(i,seed)*scale;
49	            const size_t index=std::min(size_t(position),size_t(65535));
50	            const float fraction=position-float(index);
51	            output[i]=T(table[index]+(table[index+1]-table[index])*fraction);
52	        }
53	    }
54	    double bins[32][3]={};
55	    for(size_t i=0;i<n;++i){double q=double(output[i]);int b=int(i%32);bins[b][0]+=q;bins[b][1]+=q*q;bins[b][2]+=q>=3.8?1.0:0.0;}
56	    size_t ids[8]={0,size_t(size_t(n>1?1:0)),n/7,n/3,n/2,(2*n)/3,size_t(size_t(n>1?n-2:0)),n-1};
57	    size_t bytes=output.capacity()*sizeof(T)+lookup_bytes;
58	    std::cout<<std::setprecision(13)<<"{\"storage_bytes\":"<<bytes<<",\"checksums\":[";
59	    for(int b=0;b<32;++b){if(b)std::cout<<',';std::cout<<'['<<bins[b][0]<<','<<bins[b][1]<<','<<bins[b][2]<<']';}
60	    std::cout<<"],\"samples\":[";for(int j=0;j<8;++j){if(j)std::cout<<',';std::cout<<double(output[ids[j]]);}std::cout<<"]}\n";
